import { invalidCells, userGrid } from './grid';
import { SUDOKU_SIZE } from '@sudoku/constants';
import { derived, get, writable } from 'svelte/store';

function copyGrid(grid) {
	return grid.map(row => row.slice());
}

function createExploreMode() {
	const state = writable({ active: false, origin: null });

	return {
		subscribe: state.subscribe,

		enter() {
			state.update($state => $state.active ? $state : { active: true, origin: copyGrid(get(userGrid)) });
		},

		commit() {
			state.set({ active: false, origin: null });
		},

		abandon() {
			const $state = get(state);
			if (!$state.active) return;
			userGrid.replace($state.origin);
			state.set({ active: false, origin: null });
		},

		reset() {
			const $state = get(state);
			if (!$state.active) return;
			userGrid.replace($state.origin);
		},
	};
}

export const gamePaused = writable(true);
export const exploreMode = createExploreMode();

export const gameWon = derived(
	[userGrid, invalidCells],
	([$userGrid, $invalidCells]) => {
		for (let row = 0; row < SUDOKU_SIZE; row++) {
			for (let col = 0; col < SUDOKU_SIZE; col++) {
				if ($userGrid[row][col] === 0) return false;
			}
		}
		// No empty fields...

		return ($invalidCells.length === 0);
	},
	false,
);